   #pragma omp parallel for default(none) shared(_PB_W, _PB_H, imgIn, y1, y2, a1, a2, a3, a4, b1, b2) private(i, j, ym1, ym2, xm1, yp1, yp2, xp1, xp2) schedule(static, 64)
